pub(crate) fn memory_face(
        data: &[u8],
        face_index: usize,
        size_pt: f32,
    ) -> Result<Self, FontError> {
        if read_u32_le(data, 0) == Some(PCF_FILE_VERSION) {
            return Self::pcf_face(data, face_index, size_pt);
        }
        if data.starts_with(b"PFR0") {
            return Self::pfr_face(data, face_index, size_pt);
        }
        if matches!(read_u16_le(data, 0), Some(0x0200) | Some(0x0300)) {
            return Self::winfnt_face(data, face_index, size_pt);
        }
        if bdf_text(data)
            .and_then(first_bdf_keyword)
            .is_some_and(is_bdf_probe_keyword)
        {
            if let Some(error) = parse_bdf_constructor_error(data) {
                return Err(error);
            }
            return Self::bdf_face(data, face_index, size_pt);
        }
        if data.starts_with(b"%!PS-Adobe-3.0 Resource-CIDFont") {
            return Self::cid_type1_face(data, face_index, size_pt);
        }

if type42_sfnt_data(data).is_some() {
    return Self::type42_face(data, face_index, size_pt);
}
if type1_cleartext(data).is_some() {
    return Self::type1_face(data, face_index, size_pt);
}
if data.len() >= 17 && data.iter().all(|byte| *byte < b' ') {
    // FreeType's final BDF driver probe (`bdf/bdflib.c`) skips every
    // byte below ASCII space while looking for a line.  An all-
    // control stream therefore reaches EOF with no `STARTFONT`
    // line and returns Invalid_File_Format from `bdf_load_font`;
    // `BDF_Face_Init` preserves that error for `FT_Open_Face`.
    // Keep the length guard because earlier C driver probes use
    // fixed-size frames and win the error race on shorter streams.
    return Err(FontError::InvalidFileFormat(
        "BDF stream ended before a complete line".into(),
    ));
}

fn truetype_face_with_load_mode_and_design_coords(
        data: &[u8],
        face_index: usize,
        size_pt: f32,
        load_mode: LoadMode,
        design_coords: Option<&[i32]>,
        blend_coords_16_16: Option<&[i32]>,
        variation_coordinates_set: bool,
    ) -> Result<Self, FontError> {
        // FreeType stores a 1-based named-instance selector in bits 16..30;
        // the low 16 bits still select the collection face (ftobjs.c).
        let collection_face_index = face_index & 0xFFFF;
        let (num_faces, face_offset) = tt::resolve_face_index(data, collection_face_index)?;
        let dir = tt::parse_table_directory_at(data, face_offset)?;
        let fvar = dir
            .find(data, tag(b"fvar"))
            .and_then(|bytes| tt::fvar::parse_fvar(bytes).ok());
        let avar = fvar.as_ref().and_then(|fvar| {
            dir.find(data, tag(b"avar"))
                .and_then(|bytes| tt::avar::parse_avar(bytes, fvar.axes.len()).ok())
        });

let named_instance = (face_index >> 16) & 0x7FFF;
if named_instance != 0
    && fvar
        .as_ref()
        .is_none_or(|table| named_instance > usize::from(table.instance_count))
{
    return Err(FontError::InvalidFont(format!(
        "named instance {named_instance} is unavailable"
    )));
}

let head_bytes = dir
    .find(data, tag(b"head"))
    .ok_or_else(|| FontError::InvalidFont("missing 'head' table".into()))?;
let head = tt::head::parse_head(head_bytes)?;

// tt_face_load_maxp reads its optional 26-byte frame from the SFNT
// stream after goto_table, without constraining reads to table length.
let maxp_record = dir
    .record(tag(b"maxp"))
    .ok_or_else(|| FontError::InvalidFont("missing 'maxp' table".into()))?;
let maxp_bytes = data
    .get(maxp_record.offset as usize..)

pub fn resolve_face_index(data: &[u8], face_index: usize) -> Result<(usize, usize), FontError> {
    let offsets = face_offsets(data)?;
    let count = offsets.len();
    let offset = offsets.get(face_index).copied().ok_or_else(|| {
        FontError::InvalidFont(format!(
            "face index {face_index} out of range for {count} face(s)"
        ))
    })?;
    Ok((count, offset))
}

pub(crate) fn memory_face(
        data: &[u8],
        face_index: usize,
        size_pt: f32,
    ) -> Result<Self, FontError> {
        if read_u32_le(data, 0) == Some(PCF_FILE_VERSION) {
            return Self::pcf_face(data, face_index, size_pt);
        }
        if data.starts_with(b"PFR0") {
            return Self::pfr_face(data, face_index, size_pt);
        }
        if matches!(read_u16_le(data, 0), Some(0x0200) | Some(0x0300)) {
            return Self::winfnt_face(data, face_index, size_pt);
        }
        if bdf_text(data)
            .and_then(first_bdf_keyword)
            .is_some_and(is_bdf_probe_keyword)
        {
            if let Some(error) = parse_bdf_constructor_error(data) {
                return Err(error);
            }
            return Self::bdf_face(data, face_index, size_pt);
        }
        if data.starts_with(b"%!PS-Adobe-3.0 Resource-CIDFont") {
            return Self::cid_type1_face(data, face_index, size_pt);
        }

if type42_sfnt_data(data).is_some() {
    return Self::type42_face(data, face_index, size_pt);
}
if type1_cleartext(data).is_some() {
    return Self::type1_face(data, face_index, size_pt);
}
if data.len() >= 17 && data.iter().all(|byte| *byte < b' ') {
    // FreeType's final BDF driver probe (`bdf/bdflib.c`) skips every
    // byte below ASCII space while looking for a line.  An all-
    // control stream therefore reaches EOF with no `STARTFONT`
    // line and returns Invalid_File_Format from `bdf_load_font`;
    // `BDF_Face_Init` preserves that error for `FT_Open_Face`.
    // Keep the length guard because earlier C driver probes use
    // fixed-size frames and win the error race on shorter streams.
    return Err(FontError::InvalidFileFormat(
        "BDF stream ended before a complete line".into(),
    ));
}

    match Self::truetype_face(data, face_index, size_pt) {
        Ok(face) => Ok(face),
        Err(error) if data.len() >= 118 => {
            // FreeType's WinFNT driver tries a standalone FNT header
            // after its MZ/NE probe fails. Its unknown-format result is
            // the final face-open error for a structurally plausible FNT
            // header with an unsupported version; unrelated malformed
            // buffers retain the earlier SFNT parser error.
            match Self::winfnt_face(data, face_index, size_pt) {
                Ok(face) => Ok(face),
                Err(FontError::UnknownFileFormat(message)) if has_winfnt_header_shape(data) => {
                    Err(FontError::UnknownFileFormat(message))
                }
                Err(_) => Err(error),
            }
        }
        Err(error) => Err(error),
    }
}

pub fn face_offsets(data: &[u8]) -> Result<Vec<usize>, FontError> {
    if data.len() < 4 {
        return Err(FontError::InvalidFont(
            "data too short for SFNT header".into(),
        ));
    }
    if &data[0..4] != b"ttcf" {
        parse_table_directory(data)?;
        return Ok(vec![0]);
    }
    if data.len() < 12 {
        return Err(FontError::InvalidFont(
            "TTC header too short (need 12 bytes)".into(),
        ));
    }
    let num_faces = read_u32(data, 8) as usize;
    // FreeType 2.14.3 `sfnt_open_font` (`src/sfnt/sfobjs.c`) routes a TTC
    // face-count whose offset array cannot fit in the stream through
    // `FT_Err_Array_Too_Large` before attempting allocation.
    let Some(offset_bytes) = num_faces.checked_mul(4) else {
        return Err(FontError::ArrayTooLarge);
    };
    let Some(offset_table_end) = 12usize.checked_add(offset_bytes) else {
        return Err(FontError::ArrayTooLarge);
    };
    if data.len() < offset_table_end {

        return Err(FontError::ArrayTooLarge);
    }
    let mut offsets = Vec::with_capacity(num_faces);
    for i in 0..num_faces {
        offsets.push(read_u32(data, 12 + i * 4) as usize);
    }
    Ok(offsets)
}

pub fn parse_table_directory_at(data: &[u8], base: usize) -> Result<TableDirectory, FontError> {
    let font = data
        .get(base..)
        .ok_or_else(|| FontError::InvalidFont("font offset out of range".into()))?;
    if font.len() < 12 {
        return Err(FontError::InvalidFont(
            "data too short for offset table (need 12 bytes)".into(),
        ));
    }

    let sf_version = read_u32(font, 0);
    if sf_version != TRUE_MAGIC && sf_version != OTTO_MAGIC {
        return Err(FontError::InvalidFont(format!(
            "unknown sfVersion: 0x{:08X}",
            sf_version
        )));
    }

    let num_tables = read_u16(font, 4) as usize;
    if num_tables == 0 {
        // FreeType 2.14.3 reads the SFNT offset table, then rejects both
        // TrueType and OTTO directories with no valid entries during face
        // open (`sfnt/ttload.c`: `tt_face_load_font_dir`/`check_table_dir`).
        // The public status is `FT_Err_Invalid_Stream_Operation`.

        return Err(FontError::SfntZeroTablesStreamOperation);
    }
    let dir_start = 12usize;
    let dir_end = dir_start + num_tables * 16;
    if font.len() < dir_end {
        return Err(FontError::InvalidFont(format!(
            "data too short for {num_tables} table records"
        )));
    }

    let mut records = Vec::with_capacity(num_tables);
    for i in 0..num_tables {
        let off = dir_start + i * 16;
        records.push(TableRecord {
            tag: read_u32(font, off),
            // In TTC files, table offsets remain absolute from the collection
            // start (ttload.c:tt_face_load_font_dir); don't add the face base.
            offset: read_u32(font, off + 8),
            length: read_u32(font, off + 12),
        });
    }

    Ok(TableDirectory { records })
}
